package com.cpf.starter.validation;import jakarta.validation.Validator;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;import org.springframework.context.annotation.Bean;import org.springframework.validation.beanvalidation.LocalValidatorFactoryBean;
@AutoConfiguration public class CpfValidationAutoConfiguration {@Bean @ConditionalOnMissingBean(Validator.class) LocalValidatorFactoryBean cpfValidator(){return new LocalValidatorFactoryBean();}}
